  "sql": "SELECT treatment_arm, COUNT(*) AS serious_adverse_event_count, COUNT(*) FILTER (WHERE serious = true) AS serious_adverse_event_count_total, COUNT(*) FILTER (WHERE serious = true) / COUNT(*) AS serious_adverse_event_rate FROM subjects JOIN adverse_events ON subjects.subject_id = adverse_events.subject_id WHERE adverse_events.serious = true GROUP BY treatment_arm",
